// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newDistributor) public {
        vm.assume(newDistributor != address(0) && newDistributor != address(this));
        c.addReward(address(0x1));

        bool success;
        try c.setRewardDistributor(newDistributor) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success, "Owner should be able to change rewardDistributor after addReward");
    }
}

